/**
* Converts English number words into numeric values.
* Handles 4-8 digit numbers correctly via accumulator + multiplier chain.
*
* Examples:
*  "twelve thousand five hundred" → "12500"
*  "two lakh fifty thousand"      → "250000"
*  "five crore"                   → "50000000"
*  "fifty"                        → "50"
*/
var wordsToNumbers = (text) => {
	const tokens = text.split(/\s+/);
	const out = [];
	let current = 0;
	let sub = 0;
	let hasNumber = false;
	const flush = () => {
		if (hasNumber) out.push(String(current + sub));
		current = 0;
		sub = 0;
		hasNumber = false;
	};
	for (const raw of tokens) {
		const t = raw.toLowerCase().replace(/[^a-z0-9.]/g, "");
		if (/^\d+(\.\d+)?$/.test(t)) {
			flush();
			out.push(t);
			continue;
		}
		if (t in NUMBER_WORDS) {
			const n = NUMBER_WORDS[t];
			hasNumber = true;
			if (n >= 1e7) {
				current = (current + sub || 1) * n;
				sub = 0;
			} else if (n >= 1e5) {
				current += (sub || current || 1) * n;
				sub = 0;
			} else if (n >= 1e3) {
				current += (sub || 1) * n;
				sub = 0;
			} else if (n === 100) sub = (sub || 1) * 100;
			else sub += n;
		} else {
			flush();
			if (t) out.push(raw);
		}
	}
	flush();
	return out.join(" ");
};
